			}
			ArrayBuilder<(MethodSymbol, OperatorAnalysisResultKind)> instance = ArrayBuilder<(MethodSymbol, OperatorAnalysisResultKind)>.GetInstance();
			populateResults(instance, obj);
			bool result = tryReportDiagnostics(node, binder, instance, leftDisplay, rightDisplay, diagnostics);
			instance.Free();
			return result;
			static OperatorAnalysisResultKind getBestKind(object obj2)
			{
				OperatorAnalysisResultKind operatorAnalysisResultKind = OperatorAnalysisResultKind.Undefined;
				if (!(obj2 is OverloadResolutionResult<MethodSymbol> overloadResolutionResult))
				{
					if (!(obj2 is BinaryOperatorOverloadResolutionResult binaryOperatorOverloadResolutionResult))
					{
						if (!(obj2 is UnaryOperatorOverloadResolutionResult unaryOperatorOverloadResolutionResult))
						{
							throw ExceptionUtilities.UnexpectedValue(obj2);
						}
						foreach (UnaryOperatorAnalysisResult result2 in unaryOperatorOverloadResolutionResult.Results)
						{
							if ((object)result2.Signature.Method != null && (int)result2.Kind > (int)operatorAnalysisResultKind)
							{
								operatorAnalysisResultKind = result2.Kind;
							}
						}
					}
					else
					{
						foreach (BinaryOperatorAnalysisResult result3 in binaryOperatorOverloadResolutionResult.Results)
						{
							if ((object)result3.Signature.Method != null && (int)result3.Kind > (int)operatorAnalysisResultKind)
							{
								operatorAnalysisResultKind = result3.Kind;
							}
						}
					}
				}
				else
				{
					foreach (MemberResolutionResult<MethodSymbol> item2 in overloadResolutionResult.ResultsBuilder)
					{
						OperatorAnalysisResultKind operatorAnalysisResultKind2 = mapKind(item2.Result.Kind);
						if ((int)operatorAnalysisResultKind2 > (int)operatorAnalysisResultKind)
						{
							operatorAnalysisResultKind = operatorAnalysisResultKind2;
						}
					}
				}
				return operatorAnalysisResultKind;
			}
			static bool hadAmbiguousBestMethods(ArrayBuilder<(MethodSymbol?, OperatorAnalysisResultKind)> results, SyntaxNode node2, Binder binder2, BindingDiagnosticBag diagnostics2)
			{
				if (!tryGetTwoBest(results, out var first, out var second))
				{
					return false;
				}
				Error(diagnostics2, ErrorCode.ERR_AmbigOperator, nodeToReport(node2), first, second);
				return true;
			}
			static OperatorAnalysisResultKind mapKind(MemberResolutionKind kind)
			{
				return kind switch
				{
					MemberResolutionKind.ApplicableInExpandedForm => OperatorAnalysisResultKind.Applicable, 
					MemberResolutionKind.ApplicableInNormalForm => OperatorAnalysisResultKind.Applicable, 
					MemberResolutionKind.Worse => OperatorAnalysisResultKind.Worse, 
					MemberResolutionKind.Worst => OperatorAnalysisResultKind.Worse, 
					_ => OperatorAnalysisResultKind.Inapplicable, 
				};
			}
			static SyntaxNodeOrToken nodeToReport(SyntaxNode syntaxNode)
			{
				if (syntaxNode is AssignmentExpressionSyntax assignmentExpressionSyntax)
				{
					return assignmentExpressionSyntax.OperatorToken;
				}
				if (syntaxNode is BinaryExpressionSyntax binaryExpressionSyntax)
				{
					return binaryExpressionSyntax.OperatorToken;
				}
				if (syntaxNode is PrefixUnaryExpressionSyntax prefixUnaryExpressionSyntax)
				{
					return prefixUnaryExpressionSyntax.OperatorToken;
				}
				if (syntaxNode is PostfixUnaryExpressionSyntax postfixUnaryExpressionSyntax)
				{
					return postfixUnaryExpressionSyntax.OperatorToken;
				}
				return syntaxNode;
			}
			static object? pickResultToUse(object? nonExtensionResult, object? extensionResult)
			{
				if (nonExtensionResult == null)
				{
					return extensionResult;
				}
				if (extensionResult == null)
				{
					return nonExtensionResult;
				}
				if ((int)getBestKind(nonExtensionResult) < (int)getBestKind(extensionResult))
				{
					return extensionResult;
				}
				return nonExtensionResult;
			}
			static void populateResults(ArrayBuilder<(MethodSymbol?, OperatorAnalysisResultKind)> results, object? obj2)
			{
				if (!(obj2 is OverloadResolutionResult<MethodSymbol> overloadResolutionResult))
				{
					if (!(obj2 is BinaryOperatorOverloadResolutionResult binaryOperatorOverloadResolutionResult))
					{
						if (!(obj2 is UnaryOperatorOverloadResolutionResult unaryOperatorOverloadResolutionResult))
						{
							throw ExceptionUtilities.UnexpectedValue(obj2);
						}
						foreach (UnaryOperatorAnalysisResult result4 in unaryOperatorOverloadResolutionResult.Results)
						{
							results.Add((result4.Signature.Method, result4.Kind));
						}
					}
					else
					{
						foreach (BinaryOperatorAnalysisResult result5 in binaryOperatorOverloadResolutionResult.Results)
						{
							results.Add((result5.Signature.Method, result5.Kind));
						}
					}
				}
				else
				{
					foreach (MemberResolutionResult<MethodSymbol> item3 in overloadResolutionResult.ResultsBuilder)
					{
						OperatorAnalysisResultKind item = mapKind(item3.Result.Kind);
						results.Add((item3.Member, item));
					}
				}
			}
			static bool tryGetTwoBest(ArrayBuilder<(MethodSymbol?, OperatorAnalysisResultKind)> results, [NotNullWhen(true)] out MethodSymbol? first, [NotNullWhen(true)] out MethodSymbol? second)
			{
				first = null;
				second = null;
				bool flag = false;
				foreach (var (methodSymbol, operatorAnalysisResultKind) in results)
				{
					if ((object)methodSymbol != null && operatorAnalysisResultKind == OperatorAnalysisResultKind.Applicable)
					{
						if (flag)
						{
							second = methodSymbol;
							return true;
						}
						first = methodSymbol;
						flag = true;
					}
				}
				return false;
			}
			static bool tryReportDiagnostics(SyntaxNode node2, Binder binder2, ArrayBuilder<(MethodSymbol? member, OperatorAnalysisResultKind resultKind)> results, object obj3, object? obj2, BindingDiagnosticBag diagnostics2)
			{
				if (hadAmbiguousBestMethods(results, node2, binder2, diagnostics2))
				{
					return true;
				}
				if (results.Any(((MethodSymbol? member, OperatorAnalysisResultKind resultKind) m) => m.resultKind == OperatorAnalysisResultKind.Applicable))
				{
					return false;
				}
				if (results.Any(((MethodSymbol? member, OperatorAnalysisResultKind resultKind) m) => m.resultKind == OperatorAnalysisResultKind.Worse))
				{
					return false;
				}
				if (results != null && results.Count == 1)
				{
					MethodSymbol item = results[0].member;
					if ((object)item != null)
					{
						SyntaxNodeOrToken syntax = nodeToReport(node2);
						if (obj2 == null)
						{
							Error(diagnostics2, ErrorCode.ERR_SingleInapplicableUnaryOperator, syntax, obj3, item);
						}
						else
						{
							Error(diagnostics2, ErrorCode.ERR_SingleInapplicableBinaryOperator, syntax, obj3, obj2, item);
						}
						return true;
					}
				}
				return false;
			}
		}

		internal void Free()
		{
			free(ref _nonExtensionResult);
			free(ref _extensionResult);
			static void free(ref object? result)
			{
				object obj = result;
				if (obj != null)
				{
					if (!(obj is OverloadResolutionResult<MethodSymbol> overloadResolutionResult))
					{
						if (!(obj is BinaryOperatorOverloadResolutionResult binaryOperatorOverloadResolutionResult))
						{
							if (obj is UnaryOperatorOverloadResolutionResult unaryOperatorOverloadResolutionResult)
							{
								unaryOperatorOverloadResolutionResult.Free();
							}
						}
						else
						{
							binaryOperatorOverloadResolutionResult.Free();
						}
					}
					else
					{
						overloadResolutionResult.Free();
					}
					result = null;
				}
			}
		}
	}

	protected enum OverflowChecks
	{
		Implicit,
		Disabled,
		Enabled
	}

	private class QueryTranslationState
	{
		public BoundExpression fromExpression;

		public RangeVariableSymbol rangeVariable;

		public readonly Stack<QueryClauseSyntax> clauses = new Stack<QueryClauseSyntax>();

		public SelectOrGroupClauseSyntax selectOrGroup;

		public readonly Dictionary<RangeVariableSymbol, ArrayBuilder<string>> allRangeVariables = new Dictionary<RangeVariableSymbol, ArrayBuilder<string>>();

		private int _nextTransparentIdentifierNumber;

		public static RangeVariableMap RangeVariableMap(params RangeVariableSymbol[] parameters)
		{
			RangeVariableMap rangeVariableMap = new RangeVariableMap();
			foreach (RangeVariableSymbol key in parameters)
			{
				rangeVariableMap.Add(key, ImmutableArray<string>.Empty);
			}
			return rangeVariableMap;
		}

		public RangeVariableMap RangeVariableMap()
		{
			RangeVariableMap rangeVariableMap = new RangeVariableMap();
			foreach (RangeVariableSymbol key in allRangeVariables.Keys)
			{
				rangeVariableMap.Add(key, allRangeVariables[key].ToImmutable());
			}
			return rangeVariableMap;
		}

		internal RangeVariableSymbol AddRangeVariable(Binder binder, SyntaxToken identifier, BindingDiagnosticBag diagnostics)
		{
			string valueText = identifier.ValueText;
			RangeVariableSymbol rangeVariableSymbol = new RangeVariableSymbol(valueText, binder.ContainingMemberOrLambda, identifier.GetLocation());
			bool flag = false;
			binder.ReportFieldContextualKeywordConflictIfAny(rangeVariableSymbol, identifier.Parent, identifier, diagnostics);
			foreach (RangeVariableSymbol key in allRangeVariables.Keys)
			{
				if (key.Name == valueText)
				{
					diagnostics.Add(ErrorCode.ERR_QueryDuplicateRangeVariable, identifier.GetLocation(), valueText);
					flag = true;
				}
			}
			if (!flag && diagnostics != BindingDiagnosticBag.Discarded)
			{
				new LocalScopeBinder(binder).ValidateDeclarationNameConflictsInScope(rangeVariableSymbol, diagnostics);
			}
			allRangeVariables.Add(rangeVariableSymbol, ArrayBuilder<string>.GetInstance());
			return rangeVariableSymbol;
		}

		internal void AddTransparentIdentifier(string name)
		{
			foreach (ArrayBuilder<string> value in allRangeVariables.Values)
			{
				value.Add(name);
			}
		}

		internal string TransparentRangeVariableName()
		{
			return "<>h__TransparentIdentifier" + _nextTransparentIdentifierNumber++;
		}

		internal RangeVariableSymbol TransparentRangeVariable(Binder binder)
		{
			return new RangeVariableSymbol(TransparentRangeVariableName(), binder.ContainingMemberOrLambda, null, isTransparent: true);
		}

		public void Clear()
		{
			fromExpression = null;
			rangeVariable = null;
			selectOrGroup = null;
			foreach (ArrayBuilder<string> value in allRangeVariables.Values)
			{
				value.Free();
			}
			allRangeVariables.Clear();
			clauses.Clear();
		}

		public void Free()
		{
			Clear();
		}
	}

