	private class PairedOperatorComparer : IEqualityComparer<MethodSymbol>
	{
		public static readonly PairedOperatorComparer Instance = new PairedOperatorComparer();

		private PairedOperatorComparer()
		{
		}

		public bool Equals(MethodSymbol x, MethodSymbol y)
		{
			if (Microsoft.CodeAnalysis.CSharp.Symbols.SymbolEqualityComparer.AllIgnoreOptions.Equals(x.ContainingType, y.ContainingType))
			{
				return SourceMemberContainerTypeSymbol.DoOperatorsPair(x, y);
			}
			return false;
		}

		public int GetHashCode([DisallowNull] MethodSymbol method)
		{
			EqualityComparer<Symbol> allIgnoreOptions = Microsoft.CodeAnalysis.CSharp.Symbols.SymbolEqualityComparer.AllIgnoreOptions;
			int num = allIgnoreOptions.GetHashCode(method.ContainingType);
			ImmutableArray<TypeWithAnnotations> parameterTypesWithAnnotations = method.ParameterTypesWithAnnotations;
			if (parameterTypesWithAnnotations.Length >= 1)
			{
				num = Hash.Combine(num, allIgnoreOptions.GetHashCode(parameterTypesWithAnnotations[0].Type));
			}
			return num;
		}
	}

