		case SyntaxKind.SimpleLambdaExpression:
		case SyntaxKind.ParenthesizedLambdaExpression:
		case SyntaxKind.ArrowExpressionClause:
		case SyntaxKind.SwitchExpressionArm:
			return true;
		default:
