		BoundExpression operandConversion;
		if (boundExpression.IsLiteralNull())
		{
			boundValuePlaceholder = new BoundValuePlaceholder(boundExpression.Syntax, boundExpression.Type).MakeCompilerGenerated();
			operandConversion = CreateConversion(node, boundValuePlaceholder, Conversion.NullLiteral, isCast: false, null, typeSymbol2, diagnostics);
			return new BoundAsOperator(node, boundExpression, targetType, boundValuePlaceholder, operandConversion, typeSymbol2);
		}
