					propertySyntax = null;
					return null;
				}
				throw ExceptionUtilities.UnexpectedValue(boundImplicitIndexerAccess.IndexerOrSliceAccess.Kind);
			}
			result = boundIndexerAccess.Indexer;
			receiver = boundImplicitIndexerAccess.Receiver;
			break;
		}
		default:
			receiver = null;
			propertySyntax = null;
			return null;
		}
		SyntaxNode syntax = expr.Syntax;
		switch (syntax.Kind())
		{
		case SyntaxKind.SimpleMemberAccessExpression:
		case SyntaxKind.PointerMemberAccessExpression:
