	internal static bool TryGetOptionalWellKnownType(CSharpCompilation compilation, WellKnownType type, BindingDiagnosticBag diagnostics, Location location, [NotNullWhen(true)] out NamedTypeSymbol? typeSymbol)
	{
		typeSymbol = compilation.GetWellKnownType(type);
		UseSiteInfo<AssemblySymbol> useSiteInfo = typeSymbol.GetUseSiteInfo();
		DiagnosticInfo? diagnosticInfo = useSiteInfo.DiagnosticInfo;
		if (diagnosticInfo != null && diagnosticInfo.Severity == DiagnosticSeverity.Error)
		{
			typeSymbol = null;
			return false;
		}
		useSiteInfo = new UseSiteInfo<AssemblySymbol>(null, useSiteInfo.PrimaryDependency, useSiteInfo.SecondaryDependencies);
