	private bool SatisfiesForEachPattern(SyntaxNode syntax, SyntaxNode collectionSyntax, ref ForEachEnumeratorInfo.Builder builder, bool isAsync, BindingDiagnosticBag diagnostics)
	{
		TypeSymbol returnType = builder.GetEnumeratorInfo.Method.ReturnType;
		switch (returnType.TypeKind)
		{
		case TypeKind.Submission:
			throw ExceptionUtilities.UnexpectedValue(returnType.TypeKind);
		default:
			return false;
		case TypeKind.Class:
		case TypeKind.Dynamic:
		case TypeKind.Interface:
		case TypeKind.Struct:
		case TypeKind.TypeParameter:
		{
			LookupResult instance = LookupResult.GetInstance();
			try
			{
				CompoundUseSiteInfo<AssemblySymbol> useSiteInfo = GetNewCompoundUseSiteInfo(diagnostics);
				LookupMembersInType(instance, returnType, "Current", 0, null, LookupOptions.Default, this, diagnose: false, ref useSiteInfo);
				diagnostics.Add(collectionSyntax, useSiteInfo);
				useSiteInfo = new CompoundUseSiteInfo<AssemblySymbol>(useSiteInfo);
				if (!instance.IsSingleViable)
				{
					ReportPatternMemberLookupDiagnostics(collectionSyntax, instance, returnType, "Current", warningsOnly: false, diagnostics);
					return false;
				}
				Symbol singleSymbolOrDefault = instance.SingleSymbolOrDefault;
				if (singleSymbolOrDefault.IsStatic || singleSymbolOrDefault.DeclaredAccessibility != Accessibility.Public || singleSymbolOrDefault.Kind != SymbolKind.Property)
				{
					return false;
				}
				MethodSymbol ownOrInheritedGetMethod = ((PropertySymbol)singleSymbolOrDefault).GetOwnOrInheritedGetMethod();
				if ((object)ownOrInheritedGetMethod == null)
				{
					return false;
				}
				bool num = IsAccessible(ownOrInheritedGetMethod, ref useSiteInfo);
				diagnostics.Add(collectionSyntax, useSiteInfo);
				if (!num)
				{
					return false;
				}
				builder.CurrentPropertyGetter = ownOrInheritedGetMethod;
				instance.Clear();
				MethodArgumentInfo methodArgumentInfo = FindForEachPatternMethod(syntax, collectionSyntax, returnType, isAsync ? "MoveNextAsync" : "MoveNext", instance, warningsOnly: false, diagnostics, isAsync);
				if (methodArgumentInfo == null || methodArgumentInfo.Method.IsStatic || methodArgumentInfo.Method.DeclaredAccessibility != Accessibility.Public || IsInvalidMoveNextMethod(methodArgumentInfo.Method, isAsync))
				{
					return false;
				}
				builder.MoveNextInfo = methodArgumentInfo;
				return true;
			}
			finally
			{
				instance.Free();
			}
		}
		}
	}

	private bool IsInvalidMoveNextMethod(MethodSymbol moveNextMethodCandidate, bool isAsync)
	{
		if (isAsync)
		{
			return false;
		}
		return moveNextMethodCandidate.OriginalDefinition.ReturnType.SpecialType != SpecialType.System_Boolean;
	}

	private void ReportEnumerableWarning(SyntaxNode collectionSyntax, BindingDiagnosticBag diagnostics, TypeSymbol enumeratorType, Symbol patternMemberCandidate)
	{
		CompoundUseSiteInfo<AssemblySymbol> useSiteInfo = GetNewCompoundUseSiteInfo(diagnostics);
		if (IsAccessible(patternMemberCandidate, ref useSiteInfo))
		{
			diagnostics.Add(ErrorCode.WRN_PatternBadSignature, collectionSyntax.Location, enumeratorType, MessageID.IDS_Collection.Localize(), patternMemberCandidate);
		}
		diagnostics.Add(collectionSyntax, useSiteInfo);
	}

