	private bool AllInterfacesContainsIEnumerable(SyntaxNode collectionSyntax, ref ForEachEnumeratorInfo.Builder builder, TypeSymbol type, bool isAsync, BindingDiagnosticBag diagnostics, out bool foundMultiple)
	{
		CompoundUseSiteInfo<AssemblySymbol> useSiteInfo = GetNewCompoundUseSiteInfo(diagnostics);
		NamedTypeSymbol namedTypeSymbol = GetIEnumerableOfT(type, isAsync, Compilation, ref useSiteInfo, out foundMultiple, out var needSupportForRefStructInterfaces);
		if ((object)namedTypeSymbol == null || !IsAccessible(namedTypeSymbol, ref useSiteInfo))
		{
			namedTypeSymbol = null;
			if (!isAsync)
			{
				NamedTypeSymbol specialType = Compilation.GetSpecialType(SpecialType.System_Collections_IEnumerable);
				if ((object)specialType != null && Conversions.HasImplicitConversionToOrImplementsVarianceCompatibleInterface(type, specialType, ref useSiteInfo, out needSupportForRefStructInterfaces))
				{
					namedTypeSymbol = specialType;
