			}
		}
		if ((((object)namedTypeSymbol != null) & needSupportForRefStructInterfaces) && type.ContainingModule != Compilation.SourceModule && !LocalRewriter.CanRewriteForEachAsFor(Compilation, collectionSyntax, type, out MethodSymbol _, out MethodSymbol _, BindingDiagnosticBag.Discarded))
		{
			CheckFeatureAvailability(collectionSyntax, MessageID.IDS_FeatureRefStructInterfaces, diagnostics);
		}
		diagnostics.Add(collectionSyntax, useSiteInfo);
		builder.CollectionType = namedTypeSymbol;
		return (object)namedTypeSymbol != null;
	}

	internal static NamedTypeSymbol GetIEnumerableOfT(TypeSymbol type, bool isAsync, CSharpCompilation compilation, ref CompoundUseSiteInfo<AssemblySymbol> useSiteInfo, out bool foundMultiple, out bool needSupportForRefStructInterfaces)
	{
		NamedTypeSymbol result = null;
		foundMultiple = false;
		if (type.TypeKind == TypeKind.TypeParameter)
		{
			TypeParameterSymbol typeParameterSymbol = (TypeParameterSymbol)type;
			needSupportForRefStructInterfaces = typeParameterSymbol.AllowsRefLikeType;
			GetIEnumerableOfT(typeParameterSymbol.EffectiveBaseClass(ref useSiteInfo).AllInterfacesWithDefinitionUseSiteDiagnostics(ref useSiteInfo).Concat(typeParameterSymbol.AllEffectiveInterfacesWithDefinitionUseSiteDiagnostics(ref useSiteInfo)), isAsync, compilation, ref result, ref foundMultiple);
		}
		else
		{
			needSupportForRefStructInterfaces = type.IsRefLikeType;
			GetIEnumerableOfT(type.AllInterfacesWithDefinitionUseSiteDiagnostics(ref useSiteInfo), isAsync, compilation, ref result, ref foundMultiple);
		}
		return result;
	}

	private static void GetIEnumerableOfT(ImmutableArray<NamedTypeSymbol> interfaces, bool isAsync, CSharpCompilation compilation, ref NamedTypeSymbol result, ref bool foundMultiple)
	{
		if (foundMultiple)
		{
			return;
		}
		interfaces = MethodTypeInferrer.ModuloReferenceTypeNullabilityDifferences(interfaces, VarianceKind.In);
		foreach (NamedTypeSymbol item in interfaces)
		{
			if (IsIEnumerableT(item.OriginalDefinition, isAsync, compilation))
			{
				if ((object)result != null && !TypeSymbol.Equals(item, result, TypeCompareKind.IgnoreTupleNames))
				{
					foundMultiple = true;
					break;
				}
				result = item;
			}
		}
	}

	internal static bool IsIEnumerableT(TypeSymbol type, bool isAsync, CSharpCompilation compilation)
	{
		if (isAsync)
		{
			return type.Equals(compilation.GetWellKnownType(WellKnownType.System_Collections_Generic_IAsyncEnumerable_T));
		}
		return type.SpecialType == SpecialType.System_Collections_Generic_IEnumerable_T;
	}

	private void ReportPatternMemberLookupDiagnostics(SyntaxNode collectionSyntax, LookupResult lookupResult, TypeSymbol patternType, string memberName, bool warningsOnly, BindingDiagnosticBag diagnostics)
	{
		if (lookupResult.Symbols.Any())
		{
			if (warningsOnly)
			{
				ReportEnumerableWarning(collectionSyntax, diagnostics, patternType, lookupResult.Symbols.First());
				return;
			}
			lookupResult.Clear();
			CompoundUseSiteInfo<AssemblySymbol> useSiteInfo = GetNewCompoundUseSiteInfo(diagnostics);
			LookupMembersInType(lookupResult, patternType, memberName, 0, null, LookupOptions.Default, this, diagnose: true, ref useSiteInfo);
			diagnostics.Add(collectionSyntax, useSiteInfo);
			if (lookupResult.Error != null)
			{
				diagnostics.Add(lookupResult.Error, collectionSyntax.Location);
			}
		}
		else if (!warningsOnly)
		{
			diagnostics.Add(ErrorCode.ERR_NoSuchMember, collectionSyntax.Location, patternType, memberName);
		}
	}

	private MethodArgumentInfo GetParameterlessSpecialTypeMemberInfo(SpecialMember member, SyntaxNode syntax, BindingDiagnosticBag diagnostics)
	{
		MethodSymbol methodSymbol = (MethodSymbol)GetSpecialTypeMember(member, diagnostics, syntax);
		if ((object)methodSymbol == null)
