			return null;
		}
		return MethodArgumentInfo.CreateParameterlessMethod(methodSymbol);
	}

	private MethodArgumentInfo BindDefaultArguments(MethodSymbol method, BoundExpression extensionReceiverOpt, bool expanded, SyntaxNode syntax, BindingDiagnosticBag diagnostics)
	{
		if (method.ParameterCount == 0)
		{
			return MethodArgumentInfo.CreateParameterlessMethod(method);
		}
		ArrayBuilder<BoundExpression> instance = ArrayBuilder<BoundExpression>.GetInstance(method.ParameterCount);
		if (method.IsExtensionMethod)
		{
			instance.Add(extensionReceiverOpt);
		}
		ImmutableArray<int> argsToParamsOpt = default(ImmutableArray<int>);
		BindDefaultArguments(syntax, method.Parameters, method.IsExtensionBlockMember() ? extensionReceiverOpt : null, instance, null, null, ref argsToParamsOpt, out var defaultArguments, expanded, enableCallerInfo: true, diagnostics);
		return new MethodArgumentInfo(method, instance.ToImmutableAndFree(), defaultArguments, expanded);
	}
